use zeroize::Zeroizing;
fn hex_encode(bytes: &[u8]) -> String {
    const DIGITS: &[u8; 16] = b"0123456789abcdef";
    let mut encoded = String::with_capacity(bytes.len() * 2);
    for byte in bytes {
        encoded.push(DIGITS[usize::from(byte >> 4)] as char);
        encoded.push(DIGITS[usize::from(byte & 15)] as char);
    }
    encoded
}

// Byte adapter of write_new_hex_key: replace file I/O with returned text.
pub(super) fn encode_key_file(bytes:&[u8])->Option<Zeroizing<String>>{
 let mut encoded=Zeroizing::new(hex_encode(bytes));encoded.push('\n');Some(encoded)
}

