use support::observe;
#[test]
fn recipient_key_newline_does_not_grow(){
 let observed=observe(0,0,0,||drop(key_encoding::encode_key_file(&[0x5a;32]).unwrap()));
 assert_eq!(observed.growths,0,"recipient text grew: {observed:?}");
}
#[test]
fn signing_key_newline_does_not_grow(){
 let observed=observe(0,0,0,||drop(key_encoding::encode_key_file(&[0x5a;64]).unwrap()));
 assert_eq!(observed.growths,0,"signing text grew: {observed:?}");
}
#[test]
fn abandoned_key_text_does_not_grow(){
 fn reject()->Result<(),()>{let _encoded=key_encoding::encode_key_file(&[0x5a;64]).unwrap();Err(())}
 let observed=observe(0,0,0,||assert_eq!(reject(),Err(())));
 assert_eq!(observed.growths,0,"abandoned text grew: {observed:?}");
}
#[test]
fn existing_final_owner_erases(){
 let observed=observe(0,0,0,||drop(key_encoding::encode_key_file(&[0x5a;64]).unwrap()));
 assert!(observed.copy_erased,"final text retained: {observed:?}");assert_eq!(observed.copy_releases,1);
}

